  2	
  3	public enum RatePlan {
  4	    /** Full price; the guest gets everything back when cancelling a confirmed reservation. */
  5	    STANDARD,
  6	    /** 15% off, but nothing comes back on cancellation. */
  7	    NON_REFUNDABLE,
  8	    /** Corporate plan with company-specific discounts. */
  9	    CORPORATE,
 10	    /** Weekend package: Friday to Sunday, fixed price, 50% refund on cancellation. */
 11	    WEEKEND_PACKAGE,
 12	    /** Long stay: 7+ nights with 10% discount on daily rate. */
 13	    LONG_STAY
 14	}
 15	package hotel.reservations;
 16	
 17	import hotel.rooms.Room;
 18	import java.math.BigDecimal;
 19	import java.math.RoundingMode;
 20	import java.time.DayOfWeek;
 21	import java.time.LocalDate;
 22	import java.time.Month;
 23	import java.util.Map;
 24	
 25	/**
 26	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 27	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 28	 * (half-even) at every step.
 29	 */
 30	public final class PriceCalculator {
 31	
 32	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 33	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 34	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
 35	
 36	    static final Map<String, BigDecimal> CORPORATE_DISCOUNTS = Map.of(
 37	            "TECNOSUL", new BigDecimal("0.12"),
 38	            "AGROVALE", new BigDecimal("0.18"),
 39	            "FARMAVIDA", new BigDecimal("0.25")
 40	    );
 41	
 42	    static final Map<String, BigDecimal> WEEKEND_PACKAGE_PRICES = Map.of(
 43	            "STANDARD", new BigDecimal("520.00"),
 44	            "DELUXE", new BigDecimal("820.00"),
 45	            "SUITE", new BigDecimal("1200.00")
 46	    );
 47	
 48	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
 49	        return switch (ratePlan) {
 50	            case STANDARD, NON_REFUNDABLE -> calculateStandardPrice(room, checkIn, checkOut, ratePlan);
 51	            case CORPORATE -> calculateCorporatePrice(room, checkIn, checkOut, companyCode);
 52	            case WEEKEND_PACKAGE -> calculateWeekendPackagePrice(room, checkIn, checkOut);
 53	            case LONG_STAY -> calculateLongStayPrice(room, checkIn, checkOut);
 54	        };
 55	    }
 56	
 57	    private Price calculateStandardPrice(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
 58	        int nights = 0;
 59	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 60	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 61	            subtotal = subtotal.add(nightPrice(room, night));
 62	            nights++;
 63	        }
 64	        BigDecimal discount = switch (ratePlan) {
 65	            case STANDARD -> cents(BigDecimal.ZERO);
 66	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 67	            default -> cents(BigDecimal.ZERO);
 68	        };
 69	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 70	    }
 71	
 72	    private Price calculateCorporatePrice(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
 73	        int nights = 0;
 74	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 75	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 76	            subtotal = subtotal.add(nightPrice(room, night));
 77	            nights++;
 78	        }
 79	        BigDecimal discountRate = CORPORATE_DISCOUNTS.get(companyCode);
 80	        BigDecimal discount = cents(subtotal.multiply(discountRate));
 81	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 82	    }
 83	
 84	    private Price calculateWeekendPackagePrice(Room room, LocalDate checkIn, LocalDate checkOut) {
 85	        String roomTypeStr = room.type().name();
 86	        BigDecimal fixedPrice = WEEKEND_PACKAGE_PRICES.get(roomTypeStr);
 87	        int nights = 2;
 88	        return new Price(nights, fixedPrice, cents(BigDecimal.ZERO), fixedPrice);
 89	    }
 90	
 91	    private Price calculateLongStayPrice(Room room, LocalDate checkIn, LocalDate checkOut) {
 92	        int nights = 0;
 93	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 94	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 95	            subtotal = subtotal.add(nightPrice(room, night));
 96	            nights++;
 97	        }
 98	        BigDecimal discount = cents(subtotal.multiply(LONG_STAY_DISCOUNT));
 99	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
100	    }
101	
102	    BigDecimal nightPrice(Room room, LocalDate night) {
103	        BigDecimal nightlyRate = room.nightlyRate();
104	        if (isHighSeason(night)) {
105	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
106	        }
107	        return cents(nightlyRate);
108	    }
109	
110	    /** High season: from December 15 to the end of February, and the whole of July. */
111	    static boolean isHighSeason(LocalDate date) {
112	        Month month = date.getMonth();
113	        return month == Month.JANUARY
114	                || month == Month.FEBRUARY
115	                || month == Month.JULY
116	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
117	    }
118	
119	    static BigDecimal cents(BigDecimal value) {
120	        return value.setScale(2, RoundingMode.HALF_EVEN);
121	    }
122	}
123	package hotel.reservations;
124	
125	import hotel.documents.ReservationReceipt;
126	import hotel.messages.EmailSender;
127	import hotel.rooms.Room;
128	import hotel.rooms.Rooms;
129	import java.math.BigDecimal;
130	
131	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
132	public final class ReservationService {
133	
134	    static final String HOTEL_NAME = "Pousada Maré Alta";
135	
136	    private final Rooms rooms;
137	    private final ReservationStore store;
138	    private final PriceCalculator priceCalculator;
139	    private final EmailSender emailSender;
140	
141	    public ReservationService(
142	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
143	        this.rooms = rooms;
144	        this.store = store;
145	        this.priceCalculator = priceCalculator;
146	        this.emailSender = emailSender;
147	    }
148	
149	    public synchronized Reservation create(NewReservation request) {
150	        if (!request.checkOut().isAfter(request.checkIn())) {
151	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
152	        }
153	        if (request.guests() < 1) {
154	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
155	        }
156	        validateRatePlan(request);
157	        Room room = rooms.find(request.roomNumber())
158	                .orElseThrow(() -> new HotelException(
159	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
160	        if (request.guests() > room.capacity()) {
161	            throw new HotelException(
162	                    ErrorCode.CAPACITY_EXCEEDED,
163	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
164	        }
165	        boolean roomTaken = store.all().stream()
166	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
167	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
168	        if (roomTaken) {
169	            throw new HotelException(
170	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
171	        }
172	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
173	        Reservation reservation = new Reservation(store.nextId(), request, price);
174	        store.save(reservation);
175	        return reservation;
176	    }
177	
178	    private void validateRatePlan(NewReservation request) {
179	        switch (request.ratePlan()) {
180	            case CORPORATE:
181	                if (request.companyCode() == null || !PriceCalculator.CORPORATE_DISCOUNTS.containsKey(request.companyCode())) {
182	                    throw new HotelException(
183	                            ErrorCode.INVALID_REQUEST,
184	                            "invalid or missing company code for CORPORATE plan");
185	                }
186	                break;
187	            case WEEKEND_PACKAGE:
188	                if (!isWeekendPackageDates(request.checkIn(), request.checkOut())) {
189	                    throw new HotelException(
190	                            ErrorCode.INVALID_REQUEST,
191	                            "WEEKEND_PACKAGE must be Friday to Sunday (exactly 2 nights)");
192	                }
193	                break;
194	            case LONG_STAY:
195	                int nights = Math.toIntExact(java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut()));
196	                if (nights < 7) {
197	                    throw new HotelException(
198	                            ErrorCode.INVALID_REQUEST,
199	                            "LONG_STAY requires at least 7 nights");
200	                }
201	                break;
202	            case STANDARD, NON_REFUNDABLE:
203	                break;
204	        }
205	    }
206	
207	    private boolean isWeekendPackageDates(java.time.LocalDate checkIn, java.time.LocalDate checkOut) {
208	        java.time.DayOfWeek checkInDay = checkIn.getDayOfWeek();
209	        long nights = java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
210	        return checkInDay == java.time.DayOfWeek.FRIDAY && nights == 2;
211	    }
212	
213	    public Reservation find(long reservationId) {
214	        return store.find(reservationId)
215	                .orElseThrow(() -> new HotelException(
216	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
217	    }
218	
219	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
220	    public synchronized Reservation confirm(long reservationId) {
221	        Reservation reservation = find(reservationId);
222	        if (reservation.status() != ReservationStatus.PENDING) {
223	            throw notAllowed(reservation, "confirm");
224	        }
225	        reservation.confirmPayment();
226	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
227	        emailSender.send(
228	                reservation.guest().email(),
229	                "Reserva confirmada - " + HOTEL_NAME,
230	                confirmationEmailBody(reservation, receipt));
231	        return reservation;
232	    }
233	
234	    /**
235	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
236	     * reservation was never paid, so nothing comes back).
237	     */
238	    public synchronized Reservation cancel(long reservationId) {
239	        Reservation reservation = find(reservationId);
240	        if (reservation.status() != ReservationStatus.PENDING
241	                && reservation.status() != ReservationStatus.CONFIRMED) {
242	            throw notAllowed(reservation, "cancel");
243	        }
244	        BigDecimal refund = switch (reservation.ratePlan()) {
245	            case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
246	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
247	            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().multiply(new BigDecimal("0.5")));
248	        };
249	        reservation.cancel(refund);
250	        return reservation;
251	    }
252	
253	    public synchronized Reservation checkIn(long reservationId) {
254	        Reservation reservation = find(reservationId);
255	        if (reservation.status() != ReservationStatus.CONFIRMED) {
256	            throw notAllowed(reservation, "check in");
257	        }
258	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
259	        return reservation;
260	    }
261	
262	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
263	    public synchronized ReservationReceipt checkOut(long reservationId) {
264	        Reservation reservation = find(reservationId);
265	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
266	            throw notAllowed(reservation, "check out");
267	        }
268	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
269	        return new ReservationReceipt(reservation, roomOf(reservation));
270	    }
271	
272	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
273	    public ReservationReceipt receiptCopy(long reservationId) {
274	        Reservation reservation = find(reservationId);
275	        if (!reservation.isPaid()) {
276	            throw notAllowed(reservation, "issue a receipt for");
277	        }
278	        return new ReservationReceipt(reservation, roomOf(reservation));
279	    }
280	
281	    private Room roomOf(Reservation reservation) {
282	        return rooms.find(reservation.roomNumber()).orElseThrow();
283	    }
284	
285	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
286	        return "Olá, " + reservation.guest().name() + "!\n\n"
287	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
288	                + receipt.text() + "\n"
289	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
290	                + "Até breve!\n";
291	    }
292	
293	    private static HotelException notAllowed(Reservation reservation, String operation) {
294	        return new HotelException(
295	                ErrorCode.OPERATION_NOT_ALLOWED,
296	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
297	    }
298	}

