191	                            "WEEKEND_PACKAGE must be Friday to Sunday (exactly 2 nights)");
192	                }
193	                break;
194	            case LONG_STAY:
195	                int nights = Math.toIntExact(java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut()));
196	                if (nights < 7) {
197	                    throw new HotelException(
198	                            ErrorCode.INVALID_REQUEST,
199	                            "LONG_STAY requires at least 7 nights");
200	                }
201	                break;
202	            case STANDARD, NON_REFUNDABLE:
203	                break;
204	        }
205	    }
206	
207	    private boolean isWeekendPackageDates(java.time.LocalDate checkIn, java.time.LocalDate checkOut) {
208	        java.time.DayOfWeek checkInDay = checkIn.getDayOfWeek();
209	        long nights = java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
210	        return checkInDay == java.time.DayOfWeek.FRIDAY && nights == 2;
211	    }
212	
213	    public Reservation find(long reservationId) {
214	        return store.find(reservationId)
215	                .orElseThrow(() -> new HotelException(
216	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
217	    }
218	
219	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
220	    public synchronized Reservation confirm(long reservationId) {
221	        Reservation reservation = find(reservationId);
222	        if (reservation.status() != ReservationStatus.PENDING) {
223	            throw notAllowed(reservation, "confirm");
224	        }
225	        reservation.confirmPayment();
226	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
227	        emailSender.send(
228	                reservation.guest().email(),
229	                "Reserva confirmada - " + HOTEL_NAME,
230	                confirmationEmailBody(reservation, receipt));
231	        return reservation;
232	    }
233	
234	    /**
235	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
236	     * reservation was never paid, so nothing comes back).
237	     */
238	    public synchronized Reservation cancel(long reservationId) {
239	        Reservation reservation = find(reservationId);
240	        if (reservation.status() != ReservationStatus.PENDING
241	                && reservation.status() != ReservationStatus.CONFIRMED) {
242	            throw notAllowed(reservation, "cancel");
243	        }
244	        BigDecimal refund = switch (reservation.ratePlan()) {
245	            case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
246	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
247	            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().multiply(new BigDecimal("0.5")));
248	        };
249	        reservation.cancel(refund);
250	        return reservation;
251	    }
252	
253	    public synchronized Reservation checkIn(long reservationId) {
254	        Reservation reservation = find(reservationId);
255	        if (reservation.status() != ReservationStatus.CONFIRMED) {
256	            throw notAllowed(reservation, "check in");
257	        }
258	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
259	        return reservation;
260	    }
261	
262	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
263	    public synchronized ReservationReceipt checkOut(long reservationId) {
264	        Reservation reservation = find(reservationId);
265	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
266	            throw notAllowed(reservation, "check out");
267	        }
268	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
269	        return new ReservationReceipt(reservation, roomOf(reservation));
270	    }
271	
272	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
273	    public ReservationReceipt receiptCopy(long reservationId) {
274	        Reservation reservation = find(reservationId);
275	        if (!reservation.isPaid()) {
276	            throw notAllowed(reservation, "issue a receipt for");
277	        }
278	        return new ReservationReceipt(reservation, roomOf(reservation));
279	    }
280	
281	    private Room roomOf(Reservation reservation) {
282	        return rooms.find(reservation.roomNumber()).orElseThrow();
283	    }
284	
285	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
286	        return "Olá, " + reservation.guest().name() + "!\n\n"
287	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
288	                + receipt.text() + "\n"
289	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
290	                + "Até breve!\n";
291	    }
292	
293	    private static HotelException notAllowed(Reservation reservation, String operation) {
294	        return new HotelException(
295	                ErrorCode.OPERATION_NOT_ALLOWED,
296	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
297	    }
298	}

